    public static void testALatticeIsATableAndAMissingRuleIsASpan() {
        emon.Port.Cells wd = emon.Port.newCells();
        emon.Port.Cells ln = emon.Port.newCells();
        emon.Port.Cells et = emon.Port.newCells();
        emon.Port.Cells pa = emon.Port.newCells();
        StringBuilder t = emon.Testport.newText();
        ttWord(wd, ln, et, emon.Testport.textBlob("Intro"), 7200, 7000, 10200, 7800, 0);
        ttGrid(pa, 7200, 17200, 27200, 37200, 10000, 12000, 14000, 16000);
        ttAt(wd, ln, et, emon.Testport.textBlob("Item"), 7600, 10600, 1, 0);
        ttAt(wd, ln, et, emon.Testport.textBlob("Qty"), 17600, 10600, 1, 0);
        ttAt(wd, ln, et, emon.Testport.textBlob("Price"), 27600, 10600, 1, 0);
        ttAt(wd, ln, et, emon.Testport.textBlob("Bolt"), 7600, 12600, 0, 0);
        ttAt(wd, ln, et, emon.Testport.textBlob("10"), 17600, 12600, 0, 0);
        ttAt(wd, ln, et, emon.Testport.textBlob("2.50"), 27600, 12600, 0, 0);
        ttAt(wd, ln, et, emon.Testport.textBlob("Total"), 7600, 14600, 0, 0);
        ttAt(wd, ln, et, emon.Testport.textBlob("12.50"), 17600, 14600, 0, 0);
        ttWord(wd, ln, et, emon.Testport.textBlob("Outro"), 7200, 17200, 10200, 18000, 0);
        emon.Testport.assertEq(ttRun(wd, ln, et, pa, t), 0, "lattice: well formed");
        emon.Testport.assertText(t, "P[Intro];T3r;Gh;R;Ch[Item];Ch[Qty];Ch[Price];Gb;R;C[Bolt];C[10];C[2.50];R;C[Total];Cc2[12.50];P[Outro];", "a 3 x 3 lattice with its last row's two cells joined: header, body, and the paragraphs around it");
    }
